import {
  BOX_EDGES,
  BOX_RADII,
  BOX_SHADOWS,
  BOX_SPACE,
  BOX_SURFACES,
  STACK_ALIGN,
  STACK_DIRECTIONS,
  STACK_GAPS,
  STACK_JUSTIFY
} from '../components/layout-props'

const HEADER = `/*
 * Stencil layout CSS for StStack and StBox: one rule per allowed prop value, each reading a token.
 * GENERATED by \`pnpm stencil:tokens\` from stencil/components/layout-props.ts. Do not edit by hand.
 */
`

const FLEX = {
  start: 'flex-start',
  end: 'flex-end',
  between: 'space-between',
  around: 'space-around'
}
const flex = (value: string): string => FLEX[value as keyof typeof FLEX] ?? value

/** Renders the rules for both layout components as one stylesheet. */
export function renderLayoutCss(): string {
  const rules: string[] = [
    '.st-stack { display: flex; flex-direction: column; min-width: 0; }',
    '.st-stack[data-st-wrap] { flex-wrap: wrap; }',
    '.st-box { box-sizing: border-box; box-shadow: var(--st-box-ring, 0 0 #0000), var(--st-box-shadow, 0 0 #0000); }'
  ]
  for (const direction of STACK_DIRECTIONS.filter((d) => d !== 'column')) {
    rules.push(`.st-stack[data-st-direction='${direction}'] { flex-direction: ${direction}; }`)
  }
  for (const gap of STACK_GAPS) {
    rules.push(`.st-stack[data-st-gap='${gap}'] { gap: var(--st-space-${gap}); }`)
  }
  for (const align of STACK_ALIGN) {
    rules.push(`.st-stack[data-st-align='${align}'] { align-items: ${flex(align)}; }`)
  }
  for (const justify of STACK_JUSTIFY) {
    rules.push(`.st-stack[data-st-justify='${justify}'] { justify-content: ${flex(justify)}; }`)
  }
  for (const surface of BOX_SURFACES) {
    rules.push(
      `.st-box[data-st-surface='${surface}'] { background: var(--st-color-surface-${surface}); }`
    )
  }
  for (const edge of BOX_EDGES) {
    rules.push(
      `.st-box[data-st-border='${edge}'] { border: var(--st-border-100) solid var(--st-color-border-${edge}); }`
    )
    rules.push(`.st-box[data-st-ring='${edge}'] { --st-box-ring: var(--st-ring-${edge}); }`)
  }
  for (const shadow of BOX_SHADOWS) {
    rules.push(
      `.st-box[data-st-shadow='${shadow}'] { --st-box-shadow: var(--st-shadow-${shadow}); }`
    )
  }
  for (const radius of BOX_RADII) {
    const token = typeof radius === 'number' ? `--st-space-${radius}` : `--st-radius-${radius}`
    rules.push(`.st-box[data-st-radius='${radius}'] { border-radius: var(${token}); }`)
  }
  for (const stop of BOX_SPACE) {
    rules.push(`.st-box[data-st-p='${stop}'] { padding: var(--st-space-${stop}); }`)
    rules.push(`.st-box[data-st-px='${stop}'] { padding-inline: var(--st-space-${stop}); }`)
    rules.push(`.st-box[data-st-py='${stop}'] { padding-block: var(--st-space-${stop}); }`)
  }
  return `${HEADER}\n${rules.join('\n')}\n`
}
